import random


def generate(seed: int = 0) -> list[str]:
    """The selected character is sampled from the generated string, satisfying the occurrence guarantee."""
    r = random.Random(seed)
    cases = [("loveleetcode", "e"), ("aaab", "b")]
    seen = set(cases)
    while len(cases) < 600:
        s = "".join(r.choice("abcde") for _ in range(r.randint(1, 100)))
        c = r.choice(s)
        p = (s, c)
        if p not in seen:
            seen.add(p)
            cases.append(p)
    return [f"candidate(s={s!r}, c={c!r})" for s, c in cases]


_BASE_GENERATE = generate
_BOUNDARY_CALLS = [
    "candidate(s='', c='a')"
]


def generate(seed: int = 0) -> list[str]:
    calls = _BASE_GENERATE(seed)
    return calls + [call for call in _BOUNDARY_CALLS if call not in calls]
